import assert from "node:assert/strict";import {readFileSync,statSync} from "node:fs";import {spawnSync} from "node:child_process";import {inventory,sourceFingerprint} from "./scripts/documentation-lib.mjs";import {scanSecrets} from "./scripts/ci/security.mjs";import {privateRedactionValues} from "./scripts/evidence-lib.mjs";import {checkSnapshots,readSnapshots} from "./scripts/rules/check-inventory.mjs";
const p=process.cwd(),fp=sourceFingerprint(p);
for(const id of ["RUN-20261010-039","RUN-20261010-040","RUN-20261011-001","RUN-20261011-002"]){const r=JSON.parse(readFileSync("docs/validation/runs/"+id+".json"));assert.equal(r.result,"passed");assert.equal(r.source_fingerprint,fp);assert.equal(r.clock_discontinuity,false);}
for(const f of [".env.local",".local/database.json"]){assert.equal(statSync(f).mode&0o777,0o600);assert.equal(statSync(f).uid,1000);assert.equal(spawnSync("git",["check-ignore","--quiet",f]).status,0);}
for(const f of ["docs/vision/requirements.csv","docs/vision/requirement_groups.json","docs/vision/additional_scope.csv","docs/vision/source_register.json","docs/vision/dependencies.json","docs/vision/rules_certification_template.csv","docs/vision/decision_register.csv","VALIDATION_RESULTS.json","SHA256SUMS.txt",".devcontainer/compose.yaml",".devcontainer/Dockerfile","toolchain.json","pnpm-workspace.yaml"]){const r=spawnSync("git",["show","9aa11df:"+f]);assert.equal(r.status,0);assert(readFileSync(f).equals(r.stdout),"Preservation mismatch "+f);}
const rows=["/proc/net/tcp","/proc/net/tcp6"].flatMap(f=>readFileSync(f,"utf8").trim().split("\n").slice(1).map(x=>x.trim().split(/\s+/)));const listening=rows.filter(x=>x[3]==="0A").map(x=>parseInt(x[1].split(":")[1],16));for(const port of [5173,3001,3002])assert(!listening.includes(port),"App listener remains");
const known=Object.values(privateRedactionValues(p));assert.deepEqual(scanSecrets(inventory(p).map(path=>({path,bytes:readFileSync(path)})),{knownSecrets:known}),[]);
checkSnapshots(readSnapshots());for(const a of [["scripts/rules/check-inventory.mjs","--bytes"],["scripts/rules/build-inventory.mjs","--check"]]){const r=spawnSync(process.execPath,a,{stdio:"inherit"});assert.equal(r.status,0);}
console.log("PASS same final executable fingerprint across source, full, clean and security checks",fp,"; original scope/config/archive, private files, public secret scan and listener cleanup");
